        print(f"Pending: {task['name']}")
```

## Part 2: Designing the Task Class

### Basic Class Structure

```python
class Task:
    """Represents a single task in our management system."""

    def __init__(self, name, priority=3, estimated_hours=1.0):
        self.name = name
        self.priority = priority
        self.estimated_hours = estimated_hours
        self.complete = False
        self.tags = []

    def mark_complete(self):
        self.complete = True

    def add_tag(self, tag):
        if tag not in self.tags:
            self.tags.append(tag)

    def __str__(self):
        status = "✓" if self.complete else "○"
        return f"[{status}] {self.name} (Priority: {self.priority})"
```

### Adding Validation

Real-world applications need input validation. Let's enhance our class:

```python
class Task:
    """Represents a single task with validation."""

    VALID_PRIORITIES = range(1, 6)

    def __init__(self, name, priority=3, estimated_hours=1.0):
        if not name or not isinstance(name, str):
            raise ValueError("Task name must be a non-empty string")

        if priority not in self.VALID_PRIORITIES:
            raise ValueError(f"Priority must be between 1 and 5")

        if estimated_hours <= 0:
            raise ValueError("Estimated hours must be positive")

        self.name = name
        self.priority = priority
        self.estimated_hours = estimated_hours
        self.complete = False
        self.tags = []

    def mark_complete(self):
        self.complete = True

    def add_tag(self, tag):
        if not isinstance(tag, str):
            raise TypeError("Tag must be a string")
        if tag not in self.tags:
            self.tags.append(tag)

    def __str__(self):
        status = "✓" if self.complete else "○"
        return f"[{status}] {self.name} (P{self.priority})"

    def __repr__(self):
        return f"Task('{self.name}', {self.priority}, {self.estimated_hours})"
```

## Part 3: The Task Manager

Now we'll create a manager class that handles collections of tasks:

```python
class TaskManager:
    """Manages a collection of tasks."""

    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        if not isinstance(task, Task):
            raise TypeError("Expected a Task instance")
        self.tasks.append(task)
        return task

    def create_task(self, name, priority=3, estimated_hours=1.0):
        task = Task(name, priority, estimated_hours)
        self.add_task(task)
        return task

    def find_by_name(self, name):
        """Find tasks matching a name (case-insensitive)."""
        results = []
        search_name = name.lower()
        for task in self.tasks:
            if task.name.lower() == search_name:
                results.append(task)
        return results

    def get_pending(self):
        """Return all incomplete tasks."""
        return [t for t in self.tasks if not t.complete]

    def get_completed(self):
        """Return all completed tasks."""
        return [t for t in self.tasks if t.complete]

